-- 005_chama_rpcs.sql                       STATUS: DRAFT, not applied anywhere. Requires 001-003.
-- Purpose: atomic Chama creation with no per-chama password, no slots and no creation limit (D4, D7, owner decision),
--          and the workspace list (Master Prompt 8, 9).
-- The Chama id is generated by the server (a UUID string), so ids are uniform and unguessable. Existing ids such as 'mrlees' are untouched.
begin;

drop function if exists public.create_chama_global(text, text, jsonb);   -- earlier draft that took a client-chosen id

create or replace function public.create_chama_global(cname text, cdata jsonb) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare uid uuid := auth.uid(); em text; nm text := btrim(cname); cid text := gen_random_uuid()::text;
begin
  if uid is null then raise exception 'Sign in first' using errcode = '28000'; end if;
  select lower(u.email) into em from auth.users u where u.id = uid and u.email_confirmed_at is not null;
  if em is null then raise exception 'Confirm your email first'; end if;
  if nm is null or char_length(nm) not between 2 and 80 then raise exception 'Chama name must be 2 to 80 characters'; end if;
  if cdata is null or jsonb_typeof(cdata) <> 'object' then raise exception 'Chama data is invalid'; end if;
  insert into public.chamas (id, data, name) values (cid, cdata, nm);
  insert into public.chama_members (chama_id, email, user_id, role, status) values (cid, em, uid, 'treasurer', 'active');   -- role set here, never by the client
  perform public.audit_log(cid, uid, 'chama.create', cid, jsonb_build_object('name', nm));
  return jsonb_build_object('chama_id', cid, 'role', 'treasurer');
end $$;

create or replace function public.my_workspaces() returns table (chama_id text, chama_name text, role text)
language sql stable security definer set search_path = public, pg_temp as $$
  select m.chama_id, c.name, m.role from public.chama_members m join public.chamas c on c.id = m.chama_id
  where m.user_id = auth.uid() and m.status = 'active' order by c.name nulls last, m.chama_id;
$$;

revoke all on function public.create_chama_global(text, jsonb), public.my_workspaces() from public, anon;
grant execute on function public.create_chama_global(text, jsonb), public.my_workspaces() to authenticated;
commit;
-- ROLLBACK NOTES: drop function create_chama_global(text,jsonb), my_workspaces(). Chamas already created stay valid.
